INSERT INTO `cache_filter` (`cid`, `data`, `expire`, `created`, `serialized`) VALUES ('html_full_tags::1ad7d5972dcb71b16cf9c48361ec77aa0a868154bbc61e423cdb649e90bbefb9','<div id=\"street_view\" class=\"clearfix align-center\"><img alt=\"The Birch Hotel\" title=\"The Birch Hotel\" src=\"/sites/all/themes/md_minimal/images/venue/birch-hotel-exterior4.jpg\" /></div>\n<div class=\"clearfix column_small\">\n<p class=\"spaced_description\">\nThe Birch Hotel, Lewes Road, Haywards Heath, West Sussex, RH17 7SF\n</p>\n<p class=\"spaced_description\">Tel: 01444-451565</p>\n<p>For more information about the club go to: <a class=\"flarge white\" href=\"http://www.birchhotel.co.uk/\">www.birchhotel.co.uk/</a></p>\n</div>',0,1411241984,0),('html_full_tags::1cbc1fc6617a0fde4feeaedd4ea51137d14b2f41dfbcb581758e1f8d88f7ff00','<div class=\"clearfix\">\n<ul class=\"unstyled white\"><li><a href=\"http://www.comedyblogedy.com\" class=\"white\">Comedy Blogedy</a></li>\n<li><a href=\"http://www.birchhotel.co.uk\" class=\"white\">The Birch Hotel</a></li>\n<li><a href=\"http://www.chortle.co.uk/\" class=\"white\">Chortle</a>\n</li></ul></div>',0,1411215529,0),('html_full_tags::c48964e944b938ecdf3ec18209c68e7b3b6b74319f93d435c27486d9aa716765','<p>Danny\'s can be found just north of Brighton at the Birch Hotel in Haywards Heath directly on the London - Brighton line and just off the M23.</p>\n<p class=\"column_small flarge\">There is ample free parking on site and nearby.</p>\n<p class=\"column_small\"><a href=\"/venue\" class=\"btn btn-info\">How to find us</a></p>',0,1411215564,0),('html_full_tags::c6c604cb2d821212683f92df208c52078af9f0aa0bb9b6b9c48b07404810e073','<div class=\"clearfix column_small\">\n<p>If you would like to appear in the show, please contact us at <a class=\"white\" href=\"mailto:danny.kington@gmail.com\">danny.kington@gmail.com</a>, preferably with a clip of one of your recent performances.</p>\n</div>\n\n\n<div class=\"clearfix column_small\">\n<header class=\"column_title\"><h4>Our Team</h4>\n</header><ul class=\"unstyled\"><li><a href=\"/team/ian-lay\">Ian Lay Entertainments</a></li>\n</ul></div>\n\n<aside class=\"widget\"><header class=\"column_title\"><h4>Reviews</h4></header><p class=\"read-more\"><a class=\"white\" href=\"http://www.tripadvisor.co.uk/Attraction_Review-g504221-d3985810-Reviews-Danny_s_Comedy_Club-Haywards_Heath_West_Sussex_England.html\">\nTrip Advisor Reviews</a></p>\n</aside>',0,1411215529,0),('html_full_tags::fe04a9dc88d3f3be8d4f6bc63a9a80f45a4c6d8460e7551dab849457c091920a','<p></p>',0,1411215564,0);
