INSERT INTO `cache_page` (`cid`, `data`, `expire`, `created`, `serialized`) VALUES ('http://www.dannyscomedyclub.com/','a:4:{s:4:\"path\";s:4:\"node\";s:4:\"body\";s:105667:\"<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML+RDFa 1.0//EN\"\n  \"http://www.w3.org/MarkUp/DTD/xhtml-rdfa-1.dtd\">\n<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"en\" version=\"XHTML+RDFa 1.0\" dir=\"ltr\"\n  \n  xmlns:content=\"http://purl.org/rss/1.0/modules/content/\"\n  xmlns:dc=\"http://purl.org/dc/terms/\"\n  xmlns:foaf=\"http://xmlns.com/foaf/0.1/\"\n  xmlns:og=\"http://ogp.me/ns#\"\n  xmlns:rdfs=\"http://www.w3.org/2000/01/rdf-schema#\"\n  xmlns:sioc=\"http://rdfs.org/sioc/ns#\"\n  xmlns:sioct=\"http://rdfs.org/sioc/types#\"\n  xmlns:skos=\"http://www.w3.org/2004/02/skos/core#\"\n  xmlns:xsd=\"http://www.w3.org/2001/XMLSchema#\">\n\n<head profile=\"http://www.w3.org/1999/xhtml/vocab\">\n  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n<meta property=\"og:type\" content=\"website\" />\n<meta property=\"og:url\" content=\"http://www.dannyscomedyclub.com/\" />\n<meta name=\"generator\" content=\"Drupal 7 (http://drupal.org)\" />\n<link rel=\"shortcut icon\" href=\"http://www.dannyscomedyclub.com/sites/all/themes/md_minimal/favicon.ico\" type=\"image/vnd.microsoft.icon\" />\n<meta property=\"og:site_name\" content=\"Danny&#039;s Comedy Club\" />\n<meta property=\"og:title\" content=\"Danny&#039;s Comedy Club\" />\n<link rel=\"shortlink\" href=\"http://www.dannyscomedyclub.com/\" />\n<meta name=\"description\" content=\"Danny’s Comedy Club has shows on the last Friday of every month. Doors open at 7.30pm, with Curtain-up at 8.30pm. We recommend you arrive early to get the best seats. Danny&#039;s can be found just north of Brighton at the Birch Hotel in Haywards Heath directly on the London - Brighton line and just off the M23.\" />\n<meta name=\"abstract\" content=\"Danny’s Comedy Club has shows on the last Friday of every month. Doors open at 7.30pm, with Curtain-up at 8.30pm. We recommend you arrive early to get the best seats. Danny&#039;s can be found just north of Brighton at the Birch Hotel in Haywards Heath directly on the London - Brighton line and just off the M23.\" />\n<meta name=\"keywords\" content=\"Stand-up Comedy, Danny&#039;s, Brighton, Danny, Comedy Clubs, stage, microphone, Haywards Heath, Kington, Entertainment, Sussex, Stand-up, Comedians, south-east, Night-out, Auditions, singing, open-mic, acts, theater\" />\n<meta name=\"news_keywords\" content=\"Stand-up Comedy, Brighton, Music, Singing, stage, microphone, Brighton, Danny&#039;s, Comedy Clubs, Entertainment, Comedians, Comics, performance, singing, acts, theater\" />\n<link rel=\"canonical\" href=\"http://www.dannyscomedyclub.com/\" />\n  <title>\n      Haywards Heath, United Kingdom - Danny&#039;s Comedy Club  </title>\n  <style type=\"text/css\" media=\"all\">@import url(\"http://www.dannyscomedyclub.com/sites/default/packages/bootstrap/css/bootstrap.min.css?nc78v4\");\n@import url(\"http://www.dannyscomedyclub.com/sites/default/packages/bootstrap/css/bootstrap-responsive.min.css?nc78v4\");\n@import url(\"http://www.dannyscomedyclub.com/sites/all/themes/md_minimal/css/style.min.css?nc78v4\");</style>\n<style type=\"text/css\" media=\"all\">@import url(\"http://www.dannyscomedyclub.com/sites/default/packages/jQuery.jPlayer.2.4.0/jPlayer.Blue.Monday.2.4.0/blue.monday/jplayer.blue.monday.css?nc78v4\");</style>\n  <meta http-equiv=\"content-language\" content=\"en-gb\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<!--[if lte IE 8]>\n    <script src=\"/sites/all/themes/md_minimal/js/html5.js\" type=\"text/javascript\"></script>\n    <script src=\"/sites/default/packages/PIE/PIE.js\" type=\"text/javascript\"></script>\n<![endif]-->\n</head>\n<body class=\"html front not-logged-in no-sidebars page-node body-patternbg claro\" >\n    <div class=\"fixed-image page_wrapper hidden-phone\"></div>\n    <div class=\"fixed-image page_container hidden-phone\"></div>\n    <aside class=\"region region-page-top\">\n\n	<div class=\"content\">\n	  	</div>\n\n</aside> <!-- region -->    <div id=\"page\" class=\"page\">\n\n  <!-- ______________________ HEADER _______________________ -->\n  \n    <header class=\"header row-fluid\">\n        <div class=\"container mast-head\">\n            <div class=\"clearfix\">\n                <div class=\"span4 logo-container\">\n                    <h1 class=\"element-absent\" itemprop=\"sourceOrganization\">Danny\'s Comedy Club</h1>\n                    <div itemscope itemtype=\"http://schema.org/ComedyClub\">\n                                            <span itemprop=\"logo\" itemscope itemtype=\"http://schema.org/ImageObject\"><a itemprop=\"discussionUrl\" href=\"/\">\n                            <img itemprop=\"contentUrl\" src=\"http://www.dannyscomedyclub.com/sites/all/themes/md_minimal/logo.png\" alt=\"Danny\'s Comedy Club Logo\" title=\"Danny\'s Comedy Club Logo\" />\n                        </a></span>\n                                                                <h3 class=\"site-tagline\">The South’s Newest and Exciting Stand-Up Venue</h3>\n                                        </div>\n                </div>\n                \n                <div class=\"span4 white\" itemscope itemtype=\"http://schema.org/ComedyClub\">\n                                    </div>\n                \n                <div class=\"span4 white\">\n                                        <aside class=\"social-networking-following clearfix column_small\">\n                        <div class=\"clearfix\">\r\n	<p>Follow Us on:</p>\r\n	<p><span><a target=\"_blank\" href=\"http://www.twitter.com/DannysComedy\"><img src=\"/sites/all/themes/md_minimal/images/icons/social-networking/1373587805_twitter_circle_color.png\" /></a></span>\r\n        <span><a target=\"_blank\" href=\"http://www.facebook.com/DannysComedyClub\"><img src=\"/sites/all/themes/md_minimal/images/icons/social-networking/1373587771_facebook_circle_color.png\" /></a></span>\r\n<span><a target=\"_blank\" href=\"http://www.youtube.com/dannyscomedyclubcom\"><img src=\"/sites/all/themes/md_minimal/images/icons/social-networking/1373587705_youtube_circle_color.png\" /></a></span>\r\n        </p>\r\n</div>                    </aside>\n                                        \n                                        <aside class=\"social-networking-sharing clearfix column_small\">\n                        <div class=\"clearfix\">\r\n        <p>Share on:</p>\r\n        <a class=\"share-trigger btn btn-info btn-mini white\">Click to Share</a>\r\n	<div class=\"addthis_toolbox addthis_default_style element-absent share-links\">\r\n		<a class=\"addthis_button_facebook_like\" fb:like:layout=\"button_count\"></a>\r\n		<a class=\"addthis_button_tweet\"></a>\r\n		<a class=\"addthis_counter addthis_pill_style\"></a>\r\n	</div>\r\n</div>                    </aside>\n                                    </div>\n            </div>\n            \n                        <div class=\"navigation border_radius\" itemscope itemtype=\"http://schema.org/SiteNavigationElement\">\n                <ul id=\"main-menu\" class=\"nav nav-pills\"><li class=\"menu-119 first active\"><a href=\"/\" title=\"\" class=\"active\">Home</a></li>\n<li class=\"menu-479\"><a href=\"/artistes\">Artistes</a></li>\n<li class=\"menu-370\"><a href=\"/shows\">Shows</a></li>\n<li class=\"menu-123\"><a href=\"/venue\" title=\"\">Venue</a></li>\n<li class=\"menu-255\"><a href=\"/about-us\">About Us</a></li>\n<li class=\"menu-256 last\"><a href=\"/contact-us\">Contact Us</a></li>\n</ul>            </div>\n                    </div>\n    </header>\n\n  <!-- ______________________ MAIN _______________________ -->\n\n  <section class=\"page_holder container\">\n              <div id=\"content-header\">\n\n          \n                      <hgroup class=\"column_title\">\n                <h1>Shows at Danny&#039;s Comedy Club</h1>\n            </hgroup>\n          \n                    \n                      <div class=\"tabs\"></div>\n          \n                    \n        </div>\n      \n  	<div class=\"clearfix decolumn_mini\">  \n                    <div class=\"row-fluid\">\n              <div id=\"main\" class=\"span8\">\n                \n    <section class=\"akordeon column_small\">\n        <div class=\"akordeon-item\">\n            <section itemscope itemtype=\"http://schema.org/Event\" class=\"clearfix\">\n\n    <div class=\"akordeon-item-head clearfix\">\n        <div class=\"akordeon-item-head-container\">\n            <header class=\"akordeon-heading decolumn_mini entity entity-show show-show\"  about=\"/shows/28-nov-2014\" typeof=\"\">\n                <h3 class=\"decolumn_mini\">\n                    <a href=\"/shows/28-nov-2014\" class=\"white\" itemprop=\"name\">Friday, 28th November 2014</a>\n                </h3>\n                <div class=\"actions-links fsmall\">\n                    <span class=\"action-link\">\n                        <a class=\"action-link-view btn btn-warning\" itemprop=\"url\" href=\"/shows/28-nov-2014\">View Show</a>\n                    </span>\n                </div>\n            </header>\n        </div>\n    </div>\n    \n    <div class=\"akordeon-item-body\">\n        <div class=\"akordeon-item-content\">\n            <div class=\"white column_small decolumn_mini\" itemtype=\"http://schema.org/EventVenue\" itemprop=\"location\" itemscope>\n                            <span>Venue: </span>\n                <span><a itemprop=\"url\" href=\"/venue/birch-hotel\"><span itemprop=\"name\">Birch Hotel, Haywards Heath<span></a></span>\n                        </div>\n            <article class=\"entity entity-performance performance-performance \"  about=\"/node/323\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/323\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/laura-lexx\"><span itemprop=\"name\">Laura Lexx</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/323\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Finalist at Chortle Student Comedy 2009</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>West country comedian, actress and writer Laura Lexx is a uniquely gleeful performer who indulges her audience in an unrelenting childish attention. </p></div>...<div class=\"more-link\"><a href=\"/artistes/laura-lexx\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Next-generation Lucy Porter        <p class=\"clearfix column_mini large\"><strong >Chortle</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Assured stage presence and very funny        <p class=\"clearfix column_mini large\"><strong >Lonestar Comedy Club</strong></p>\n                <p class=\"clearfix column_mini large\"><strong >Ian Stewart</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Laura-Lexx.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Laura-Lexx.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Laura-Lexx_w150.jpg\" alt=\"Laura Lexx, Stand-up Comedian\" \n         title=\"Laura Lexx, Stand-up Comedian\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/324\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/324\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/stu-turner\"><span itemprop=\"name\">Stu Turner</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/324\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>A consummate performer who comes to us highly recommended, Stu Turner blends comedy and magic with absolute nonsense. </p></div>...<div class=\"more-link\"><a href=\"/artistes/stu-turner\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Stu made the night unique and broke up the typical stand up acts with magic AND comedy that the crowd loved        <p class=\"clearfix column_mini large\"><strong >Point and Laugh Comedy</strong></p>\n                <p class=\"clearfix column_mini large\"><strong >Will Pointing</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Stu combines comedy and magic with great aplomb. Audiences love him        <p class=\"clearfix column_mini large\"><strong >Way Out West Comedy Club</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Stu is a cut above the usual magician/comic stock        <p class=\"clearfix column_mini large\"><strong >Comedy Heat</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Stu-Turner.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Stu-Turner.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Stu-Turner_w150.jpg\" alt=\"Stu Turner, Stand-up Comedian\" \n         title=\"Stu Turner, Stand-up Comedian\" />\n</div>\n        </aside>\n    </div>\n</article>        </div>\n    </div>\n    \n</section><section itemscope itemtype=\"http://schema.org/Event\" class=\"clearfix\">\n\n    <div class=\"akordeon-item-head clearfix\">\n        <div class=\"akordeon-item-head-container\">\n            <header class=\"akordeon-heading decolumn_mini entity entity-show show-show\"  about=\"/shows/31-oct-2014\" typeof=\"\">\n                <h3 class=\"decolumn_mini\">\n                    <a href=\"/shows/31-oct-2014\" class=\"white\" itemprop=\"name\">Friday, 31st October 2014</a>\n                </h3>\n                <div class=\"actions-links fsmall\">\n                    <span class=\"action-link\">\n                        <a class=\"action-link-view btn btn-warning\" itemprop=\"url\" href=\"/shows/31-oct-2014\">View Show</a>\n                    </span>\n                </div>\n            </header>\n        </div>\n    </div>\n    \n    <div class=\"akordeon-item-body\">\n        <div class=\"akordeon-item-content\">\n            <div class=\"white column_small decolumn_mini\" itemtype=\"http://schema.org/EventVenue\" itemprop=\"location\" itemscope>\n                            <span>Venue: </span>\n                <span><a itemprop=\"url\" href=\"/venue/birch-hotel\"><span itemprop=\"name\">Birch Hotel, Haywards Heath<span></a></span>\n                        </div>\n            <article class=\"entity entity-performance performance-performance \"  about=\"/node/321\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/321\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/pete-beckley\"><span itemprop=\"name\">Pete Beckley</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/321\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Last Minute Comedian of the Year 2012</div>\n<div class=\"clearfix\">Reading Comedy Festival New Act of the Year 2012</div>\n<div class=\"clearfix\">Winner of the Palace Bars Comedy Awards 2012</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>With a deadpan delivery and sometimes surreal take on things, multiple award winner Pete has performed all over the UK alongside some of the biggest names in comedy, including Reginald D.</p></div>...<div class=\"more-link\"><a href=\"/artistes/pete-beckley\" title=\"Read More\">More</a></div></div>\n\n            \n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Pete-Beckley.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Pete-Beckley.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Pete-Beckley_w150.jpg\" alt=\"Pete Beckley, Reading Comedy Festival New Act of the Year 2012\" \n         title=\"Pete Beckley, Reading Comedy Festival New Act of the Year 2012\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/322\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/322\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/john-pendal\"><span itemprop=\"name\">John Pendal</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/322\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Semi-finalist at the Leicester Square New Act of the Year in 2012</div>\n<div class=\"clearfix\">Semi-finalist at the Leicester Square New Act of the Year in 2013</div>\n<div class=\"clearfix\">Semi-finalist at the So You Think You’re Funny awards in 2011</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>A full-time comic since 2010, John is another act bringing to Danny’s Comedy Club a wealth of experience and a great pedigree.</p></div>...<div class=\"more-link\"><a href=\"/artistes/john-pendal\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        John delivered ballsy comedy in an audacious style that kept the audience laughing throughout his set...        <p class=\"clearfix column_mini large\"><strong >House of Stand Up</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        John Pendal opened for us and the audience loved him. Great act.        <p class=\"clearfix column_mini large\"><strong >CAN Comedy</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        John Pendal was in top form and had the crowd roaring with laughter.        <p class=\"clearfix column_mini large\"><strong >Windy City Times, Chicago</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/John-Pendal.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/John-Pendal.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/John-Pendal_w150.jpg\" alt=\"John Pendal, Stand-up Comedian\" \n         title=\"John Pendal, Stand-up Comedian\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/388\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/388\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/ian-miller\"><span itemprop=\"name\">Ian Miller</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/388\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Finalist at the Laughing Horse New Act of the Year Contest 2012</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Hilarious and slightly surreal, Ian has been performing stand up often and successfully since 2009.</p></div>...<div class=\"more-link\"><a href=\"/artistes/ian-miller\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Brilliantly funny and destroying the public image of superman with every gig.        <p class=\"clearfix column_mini large\"><strong >Freshly Squeezed Comedy</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Ian Miller has taken superheroes to a new level and with his geeky wit, controls the room and makes us laugh at the stereotypes! One to watch.        <p class=\"clearfix column_mini large\"><strong >Wisecrack Comedy</strong></p>\n                <p class=\"clearfix column_mini large\"><strong >Will Pointing</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Ian-Miller.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Ian-Miller.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Ian-Miller_w150.jpg\" alt=\"Ian Miller, Finalist at the Laughing Horse New Act of the Year Contest 2012\" \n         title=\"Ian Miller, Finalist at the Laughing Horse New Act of the Year Contest 2012\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/389\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/389\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/george-rigden\"><span itemprop=\"name\">George Rigden</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/389\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>A relative newcomer, Bristol-based George is currently taking the comedy world by storm and we anticipate a great future for him!</p></div>...<div class=\"more-link\"><a href=\"/artistes/george-rigden\" title=\"Read More\">More</a></div></div>\n\n            \n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/George-Rigden.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/George-Rigden.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/George-Rigden_w150.jpg\" alt=\"George Rigden\" \n         title=\"George Rigden\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance performer_act_first\"  about=\"/node/391\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/391\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/graham-milton\"><span itemprop=\"name\">Graham Milton</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/391\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        Intelligent and cerebral, Graham has become a firm fixture at all the comedy clubs of substance around the country.</div>...<div class=\"more-link\"><a href=\"/artistes/graham-milton\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        I have now seen Graham four times. As usual, he was original and quite brilliant.        <p class=\"clearfix column_mini large\"><strong >Dave Dinsdale</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        I\'ve seen Graham a bunch over the last year. Saw him tonight at a new material night, where every joke got laughs and every routine got a round of applause. Completely nailed his world weary misanthropic persona.        <p class=\"clearfix column_mini large\"><strong >Paul Savage</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Graham_Milton.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Graham_Milton.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Graham_Milton_w150.jpg\" alt=\"Graham Milton\" \n         title=\"Graham Milton\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance performer_act_first\"  about=\"/node/395\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/395\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/chris-betts\"><span itemprop=\"name\">Chris Betts</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/395\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Finalist at the Comedy Knights New Act of the Year 2013</div>\n<div class=\"clearfix\">Finalist at the Up The Creek \"One to watch\" 2013</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Over the last five years, Chris Betts has performed all across Canada and the United States at independent venues, comedy clubs, and international festivals including the Comedy Works in Montreal, </p></div>...<div class=\"more-link\"><a href=\"/artistes/chris-betts\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Chris Betts is tremendous.        <p class=\"clearfix column_mini large\"><strong >Such Small Portions</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Betts is in the upper echelon of the city’s performers; universally respected and admired for his professionalism, dedication and unique perspective of the world        <p class=\"clearfix column_mini large\"><strong >Examiner.com</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        unhurried delivery that reeled the audience in... unflappable stage presence.        <p class=\"clearfix column_mini large\"><strong >London is funny</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Chris-Betts.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Chris-Betts.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Chris-Betts_w150.jpg\" alt=\"Chris Betts\" \n         title=\"Chris Betts\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/396\" typeof=\"\" itemscope itemtype=\"http://schema.org/MusicEvent\">\n    <meta itemprop=\"url\" content=\"/node/396\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/dan-russell\"><span itemprop=\"name\">Dan Russell</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/396\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        Dan has completed six seasons performing in Spain where he has scooped a clutch of awards and will this year be in Corfu, Greece.</div>...<div class=\"more-link\"><a href=\"/artistes/dan-russell\" title=\"Read More\">More</a></div></div>\n\n            \n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Dan-Russell.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Dan-Russell.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Dan-Russell_w150.jpg\" alt=\"Dan Russell\" \n         title=\"Dan Russell\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance performer_act_first\"  about=\"/node/398\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/398\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/richard-stainbank\"><span itemprop=\"name\">Richard Stainbank</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/398\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Finalist at the Laughing Horse New Act of the Year Contest 2013</div>\n<div class=\"clearfix\">Runner up in Comedy Knights Fresh Comedian of the Year 2013</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Widely respected and popular with audiences wherever he goes, Richard has been gigging around London and the south east for the past six years, was runner up in Comedy Knights Fresh Comedian of the</p></div>...<div class=\"more-link\"><a href=\"/artistes/richard-stainbank\" title=\"Read More\">More</a></div></div>\n\n            \n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Richard-Stainbank.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Richard-Stainbank.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Richard-Stainbank_w150.jpg\" alt=\"Richard Stainbank\" \n         title=\"Richard Stainbank\" />\n</div>\n        </aside>\n    </div>\n</article>        </div>\n    </div>\n    \n</section><section itemscope itemtype=\"http://schema.org/Event\" class=\"clearfix\">\n\n    <div class=\"akordeon-item-head clearfix\">\n        <div class=\"akordeon-item-head-container\">\n            <header class=\"akordeon-heading decolumn_mini entity entity-show show-show\"  about=\"/shows/26-sept-2014\" typeof=\"\">\n                <h3 class=\"decolumn_mini\">\n                    <a href=\"/shows/26-sept-2014\" class=\"white\" itemprop=\"name\">Friday, 26th September 2014</a>\n                </h3>\n                <div class=\"actions-links fsmall\">\n                    <span class=\"action-link\">\n                        <a class=\"action-link-view btn btn-warning\" itemprop=\"url\" href=\"/shows/26-sept-2014\">View Show</a>\n                    </span>\n                </div>\n            </header>\n        </div>\n    </div>\n    \n    <div class=\"akordeon-item-body\">\n        <div class=\"akordeon-item-content\">\n            <div class=\"white column_small decolumn_mini\" itemtype=\"http://schema.org/EventVenue\" itemprop=\"location\" itemscope>\n                            <span>Venue: </span>\n                <span><a itemprop=\"url\" href=\"/venue/birch-hotel\"><span itemprop=\"name\">Birch Hotel, Haywards Heath<span></a></span>\n                        </div>\n            <article class=\"entity entity-performance performance-performance \"  about=\"/node/371\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/371\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/sheraz-yousef\"><span itemprop=\"name\">Sheraz Yousef</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/371\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        An incredibly likeable and popular new talent on the comedy circuit. Sheraz’s clever and slickly delivered act is a joy to watch and draws in his audience.</div>...<div class=\"more-link\"><a href=\"/artistes/sheraz-yousef\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        ... excellent mimicry being incorporated into a very funny set...    </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        ... fresh humour, it appealed to everyone...    </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Sheraz-Yousaf-2.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Sheraz-Yousaf-2.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Sheraz-Yousaf-2_w150.jpg\" alt=\"Sheraz Yousef\" \n         title=\"Sheraz Yousef\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/372\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/372\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/cylvian-flynn\"><span itemprop=\"name\">Cylvian Flynn</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/372\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Originally a London girl, Cylvian has fronted several bands as well as solo ventures performing at theatres and music events large and small to great acclaim.</p></div>...<div class=\"more-link\"><a href=\"/artistes/cylvian-flynn\" title=\"Read More\">More</a></div></div>\n\n            \n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Cylvian-Flynno.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Cylvian-Flynno.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Cylvian-Flynno_w150.jpg\" alt=\"Cylvian Flynn, Singer\" \n         title=\"Cylvian Flynn, Singer\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance performer_act_first\"  about=\"/node/376\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/376\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/joe-sutherland\"><span itemprop=\"name\">Joe Sutherland</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/376\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"><span class=\"pull-left\">&nbsp;&nbsp;<span class=\"badge\"><div class=\"clearfix\">Finalist at Colchester New Comedian of the Year 2014</div>\n<div class=\"clearfix\">Finalist at Comedy Cafe New Act of the Year 2013</div>\n<div class=\"clearfix\">Finalist at Comedy Knights Fresh Comedian of 2014</div>\n</span></span></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Former child actor, ex-model and fashion school drop-out. Based in London, Joe makes his way as a performer, writer and all-round hustler. </p></div>...<div class=\"more-link\"><a href=\"/artistes/joe-sutherland\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Nihilistic heart-throb ... effortless presence        <p class=\"clearfix column_mini large\"><strong >The Goodfather Comedy Club</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        The kind of young comic you really want to hate ... but can’t help but admire for their charm and humorous self-confidence.        <p class=\"clearfix column_mini large\"><strong >Broadway Baby</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Joe-Sutherland.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Joe-Sutherland.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Joe-Sutherland_w150.jpg\" alt=\"Joe Sutherland\" \n         title=\"Joe Sutherland\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance performer_act_first\"  about=\"/node/379\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/379\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/mat-wills\"><span itemprop=\"name\">Mat Wills</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/379\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Mat started his comedy career in March 2011. He quit his [what he thought] successful IT career and became an office temp so he could concentrate on writing and performing comedy.</p></div>...<div class=\"more-link\"><a href=\"/artistes/mat-wills\" title=\"Read More\">More</a></div></div>\n\n            \n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Mat-Wills.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Mat-Wills.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Mat-Wills_w150.jpg\" alt=\"Mat Wills\" \n         title=\"Mat Wills\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance performer_act_first\"  about=\"/node/381\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/381\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/sonia-aste\"><span itemprop=\"name\">Sonia Aste</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/381\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Sonia is a witty Spanish comedian who is not afraid to poke fun at other cultures, especially her own. Her comedy is full of sparkling passion and she makes everyone part of the show. </p></div>...<div class=\"more-link\"><a href=\"/artistes/sonia-aste\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        The audience loved her!        <p class=\"clearfix column_mini large\"><strong >Marketing & Events The Albert 57 Kingston Hill</strong></p>\n                <p class=\"clearfix column_mini large\"><strong >Amy-Jane Cahalane</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Very strong stage presence, great audience rapport and confidence.        <p class=\"clearfix column_mini large\"><strong >Funny Women</strong></p>\n                <p class=\"clearfix column_mini large\"><strong >Isobel Matheson</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        One of the few performers who cheers me up the second I see her. She goes on bold adventures and can light up any room.        <p class=\"clearfix column_mini large\"><strong >Hoopla</strong></p>\n                <p class=\"clearfix column_mini large\"><strong >Steve Roe</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Sonia-Aste.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Sonia-Aste.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Sonia-Aste_w150.jpg\" alt=\"Sonia Aste\" \n         title=\"Sonia Aste\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/384\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/384\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/murray-porter\"><span itemprop=\"name\">Murray Porter</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/384\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        \"Very funny, charming and likeable performer with a real talent for storytelling and improvisation. Edgy, self deprecating and well crafted stories told with compelling style.\"</div>...<div class=\"more-link\"><a href=\"/artistes/murray-porter\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        \"Murray\'s very friendly, likeable and has a terrific stage presence. Extremely funny with very strong crowd work. I have absolutely no hesitations recommending him - he could work any room. BOOK HIM!\"        <p class=\"clearfix column_mini large\"><strong >Edinburgh Must See</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        \"Brilliant at winning the audience over and getting them onside.\"        <p class=\"clearfix column_mini large\"><strong >Monkey Box Comedy</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Murray-Porter.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Murray-Porter.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Murray-Porter_w150.jpg\" alt=\"Murray Porter, Stand-up Comedian\" \n         title=\"Murray Porter, Stand-up Comedian\" />\n</div>\n        </aside>\n    </div>\n</article>        </div>\n    </div>\n    \n</section><section itemscope itemtype=\"http://schema.org/Event\" class=\"clearfix\">\n\n    <div class=\"akordeon-item-head clearfix\">\n        <div class=\"akordeon-item-head-container\">\n            <header class=\"akordeon-heading decolumn_mini entity entity-show show-show\"  about=\"/shows/5-sept-2014\" typeof=\"\">\n                <h3 class=\"decolumn_mini\">\n                    <a href=\"/shows/5-sept-2014\" class=\"white\" itemprop=\"name\">Friday, 5th September 2014</a>\n                </h3>\n                <div class=\"actions-links fsmall\">\n                    <span class=\"action-link\">\n                        <a class=\"action-link-view btn btn-warning\" itemprop=\"url\" href=\"/shows/5-sept-2014\">View Show</a>\n                    </span>\n                </div>\n            </header>\n        </div>\n    </div>\n    \n    <div class=\"akordeon-item-body\">\n        <div class=\"akordeon-item-content\">\n            <div class=\"white column_small decolumn_mini\" itemtype=\"http://schema.org/EventVenue\" itemprop=\"location\" itemscope>\n                            <span>Venue: </span>\n                <span><a itemprop=\"url\" href=\"/venue/arora-gatwick-hotel\"><span itemprop=\"name\">Arora (Gatwick) Hotel<span></a></span>\n                        </div>\n            <article class=\"entity entity-performance performance-performance \"  about=\"/node/353\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/353\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/jo-public\"><span itemprop=\"name\">Jo Public</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/353\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>Award-winning comic Jo has been performing for three years now and runs her own Club Jolly Comedy in Worthing. She recently made the semi-finals of Funny Women. </p></div>...<div class=\"more-link\"><a href=\"/artistes/jo-public\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Jo Public never fails to deliver ... 10 out of 10!!        <p class=\"clearfix column_mini large\"><strong >Jailhouse Screamers</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Jo Public had the audience in stitches        <p class=\"clearfix column_mini large\"><strong >The Argus</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Jo-Public.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Jo-Public.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Jo-Public_w150.jpg\" alt=\"Jo Public, Stand-up Comedian\" \n         title=\"Jo Public, Stand-up Comedian\" />\n</div>\n        </aside>\n    </div>\n</article><article class=\"entity entity-performance performance-performance \"  about=\"/node/354\" typeof=\"\" itemscope itemtype=\"http://schema.org/ComedyEvent\">\n    <meta itemprop=\"url\" content=\"/node/354\" />\n    <h3 class=\"clearfix\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n        <span><a class=\"underline pull-left heading_title\" itemprop=\"url\" href=\"/artistes/mike-cox\"><span itemprop=\"name\">Mike Cox</span></a></span>\n        <span class=\"pull-right\"><a class=\"btn btn-danger\" href=\"/node/354\"> View Performance</a></span>\n    </h3>\n    <div class=\"clearfix decolumn_mini\"></div>\n    <div class=\"row-fluid\">\n        <div class=\"span10\">\n\n            <div class=\"clearfix\" itemprop=\"description\"><div class=\"field field-name-body field-type-text-with-summary field-label-hidden\">\n        <p>This Sussex based comedian is already making his mark on the comedy circuit.</p>\n</div>...<div class=\"more-link\"><a href=\"/artistes/mike-cox\" title=\"Read More\">More</a></div></div>\n\n            <div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        We love Brighton        <p class=\"clearfix column_mini large\"><strong >The Argus</strong></p>\n            </blockquote>\n\n</div><div class=\"entity entity-pressquotation pressquotation-pressquotation\"  about=\"\" typeof=\"\">\n\n    <blockquote class=\"column_small press_quotes\">\n        Genuinely funny        <p class=\"clearfix column_mini large\"><strong >The Argus</strong></p>\n            </blockquote>\n\n</div>\n        </div>\n        <aside class=\"span2\" itemprop=\"performer\" itemscope itemtype=\"http://schema.org/Person\">\n            <meta itemprop=\"image\" content=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Mike-Cox.jpg\" />\n<div class=\"field field-name-field-image field-type-image field-label-hidden\"  property=\"sioc:link foaf:depicts dcmit:Image\" resource=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Mike-Cox.jpg\">\n    <img src=\"http://www.dannyscomedyclub.com/sites/default/files/artistes-image/Mike-Cox_w150.jpg\" alt=\"Mike Cox, Stand-up Comedian\" \n         title=\"Mike Cox, Stand-up Comedian\" />\n</div>\n        </aside>\n    </div>\n</article><arti