INSERT INTO `metatag_config` (`cid`, `instance`, `config`) VALUES (1,'global:frontpage','a:10:{s:5:\"title\";a:1:{s:5:\"value\";s:11:\"[site:name]\";}s:11:\"description\";a:1:{s:5:\"value\";s:310:\"Danny’s Comedy Club has shows on the last Friday of every month. Doors open at 7.30pm, with Curtain-up at 8.30pm. We recommend you arrive early to get the best seats. Danny\'s can be found just north of Brighton at the Birch Hotel in Haywards Heath directly on the London - Brighton line and just off the M23.\";}s:8:\"abstract\";a:1:{s:5:\"value\";s:310:\"Danny’s Comedy Club has shows on the last Friday of every month. Doors open at 7.30pm, with Curtain-up at 8.30pm. We recommend you arrive early to get the best seats. Danny\'s can be found just north of Brighton at the Birch Hotel in Haywards Heath directly on the London - Brighton line and just off the M23.\";}s:8:\"keywords\";a:1:{s:5:\"value\";s:211:\"Stand-up Comedy, Danny\'s, Brighton, Danny, Comedy Clubs, stage, microphone, Haywards Heath, Kington, Entertainment, Sussex, Stand-up, Comedians, south-east, Night-out, Auditions, singing, open-mic, acts, theater\";}s:13:\"news_keywords\";a:1:{s:5:\"value\";s:164:\"Stand-up Comedy, Brighton, Music, Singing, stage, microphone, Brighton, Danny\'s, Comedy Clubs, Entertainment, Comedians, Comics, performance, singing, acts, theater\";}s:9:\"canonical\";a:1:{s:5:\"value\";s:10:\"[site:url]\";}s:9:\"shortlink\";a:1:{s:5:\"value\";s:10:\"[site:url]\";}s:8:\"og:title\";a:1:{s:5:\"value\";s:11:\"[site:name]\";}s:7:\"og:type\";a:1:{s:5:\"value\";s:7:\"website\";}s:6:\"og:url\";a:1:{s:5:\"value\";s:10:\"[site:url]\";}}'),(2,'global','a:37:{s:5:\"title\";a:1:{s:5:\"value\";s:34:\"[current-page:title] | [site:name]\";}s:11:\"description\";a:1:{s:5:\"value\";s:0:\"\";}s:8:\"abstract\";a:1:{s:5:\"value\";s:0:\"\";}s:8:\"keywords\";a:1:{s:5:\"value\";s:154:\"Stand-up Comedy, Brighton, Music, Singing, stage, microphone, Danny\'s, Comedy Clubs, Entertainment, Comedians, Comics, performance